(()=>{
'use strict';
const route=window.RICO_COURSE?'rico':new URLSearchParams(location.search).get('project');
const classes=window.RICO_COURSE||window.STUDIO_COURSES?.[route]?.classes;if(!classes)return;
classes.forEach((cl,c)=>cl.cells.forEach(it=>{const steps=window.IJR_STEP_DATA?.[route+':'+(c+1)+':'+it.id];if(steps?.length){it.referenceCode=it.code;it.microsteps=steps;it.code=steps[0].code;}}));
const steps=it=>it.microsteps||[];
function initialize(cells,id,it){
 let e=cells[id]||{};const all=steps(it);if(!all.length)return e;
 if(!Number.isInteger(e.microIndex)){
  if(typeof e.code==='string'&&e.code!==it.referenceCode&&e.code!==it.code){e={...e,microIndex:all.length-1,legacyCode:e.legacyCode||e.code||e.previousCode,legacyMode:true};}
  else{e={...e,legacyCode:e.legacyCode||e.code||e.previousCode,code:all[0].code,microIndex:0,microPassed:false,ok:false};}
 }
 e.microIndex=Math.max(0,Math.min(all.length-1,e.microIndex));cells[id]=e;return e;
}
function end(it,e){const all=steps(it);return !all.length||e.microIndex===all.length-1;}
function canNext(it,e,executed){return end(it,e)?executed:e.microPassed===true;}
function advance(it,e){const all=steps(it);if(end(it,e)||!e.microPassed)return false;const current=all[e.microIndex],next=all[e.microIndex+1];e.code+=next.code.slice(current.code.length);e.microIndex++;e.microPassed=false;e.ok=false;return true;}
function describe(it,e){const all=steps(it);if(!all.length)return {title:it.title,purpose:it.purpose,steps:it.steps};const s=all[e.microIndex||0];return {title:'Paso '+((e.microIndex||0)+1)+' / '+all.length+' · '+s.title,purpose:e.legacyMode?'Código anterior conservado. Revisa este bloque completo o usa «Iniciar guía» para construirlo desde el primer paso sin perder el respaldo.':s.explain,steps:[...s.actions,'Comprobación: '+s.expected]};}
function check(it,e){return steps(it)[e.microIndex||0]?.check||'';}
function reset(it,e){if(!steps(it).length)return;e.codeHistory=[...(e.codeHistory||[]),{code:e.code,at:new Date().toISOString(),reason:'reiniciar guía'}].slice(-3);e.legacyCode=e.legacyCode||e.code;e.code=it.code;e.microIndex=0;e.microPassed=false;e.legacyMode=false;e.ok=false;}
window.IJR_STEPS={initialize,end,canNext,advance,describe,check,reset};
})();
